from django import template
from django.template.base import token_kwargs
from djinn.core.cva import cva

register = template.Library()

checkbox_cva = cva(
    base="peer flex items-center space-x-2",
    variants={
        "variant": {
            "default": "",
            "error": "data-[checked=indeterminate]:bg-destructive data-[checked=indeterminate]:border-destructive",
        },
    },
    default_variants={
        "variant": "default",
    }
)

class CheckboxNode(template.Node):
    def __init__(self, nodelist, kwargs):
        self.nodelist = nodelist
        self.kwargs = kwargs

    def render(self, context):
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            try:
                resolved_kwargs[k] = v.resolve(context)
            except template.VariableDoesNotExist:
                resolved_kwargs[k] = ""

        final_class = checkbox_cva(**resolved_kwargs)

        known_args = ["variant", "checked", "disabled", "class", "class_name", "slot"]
        attrs = {k: v for k, v in resolved_kwargs.items() if k not in known_args}

        slot = self.nodelist.render(context) if self.nodelist else ""
        checked = resolved_kwargs.get("checked", False)
        disabled = resolved_kwargs.get("disabled", False)

        t = context.template.engine.get_template('components/checkbox.html')
        new_context = context.new({
            "class": final_class,
            "slot": slot,
            "checked": checked,
            "disabled": disabled,
            "attrs": attrs,
            **resolved_kwargs
        })
        return t.render(new_context)

@register.tag('djinn_checkbox')
def djinn_checkbox(parser, token):
    bits = token.split_contents()
    kwargs = token_kwargs(bits[1:], parser)
    nodelist = parser.parse(('enddjinn_checkbox',))
    parser.delete_first_token()
    return CheckboxNode(nodelist, kwargs)
